import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1209, own='cte_132.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("881.d.1.A",3,"A paint-shop apprentice explains a color delay to an upset customer in plain words and then confirms the plan in a text. This shows:","effective oral and written communication with customers, coworkers and vendors",["avoiding the customer","using only slang","hiding the delay"],"Clear spoken and written updates.")
H("881.d.1.A",4,"Which habit best shows effective communication in a refinish shop?","Repeating a customer's request back and noting it on the work order",["Guessing what the customer wants","Skipping notes to save time","Talking only to coworkers"],"Confirm and document.")
H("881.d.1.B",3,"A painter fills in the paint code, number of panels and materials used on a refinish order so the office can bill. This is:","technical writing used to complete paint and refinishing orders",["a drawing exercise","a sales pitch","a safety drill"],"Orders need accurate details.")
H("881.d.1.B",4,"A refinish order that leaves out the mixing ratio can cause:","a repeat job or a mismatched color",["a faster repair","a bigger discount","a cleaner booth"],"Missing data causes rework.")
H("881.d.1.C",3,"Before spraying a new waterborne basecoat, Tomas reads the technical data sheet for flash times and reducer. He is:","locating, reading and interpreting technical documents",["ignoring directions","guessing times","watching a video only"],"The TDS gives product directions.")
H("881.d.1.C",4,"A technical data sheet is the best source for a product's:","mix ratio, recoat window and drying times",["owner's name","shop hours","insurance claim"],"TDS holds product specs.")
H("881.d.1.D",3,"A service bulletin says a clearcoat batch needs a different activator. A painter checks the bulletin before mixing. This shows:","competency in using and interpreting service repair bulletins",["skipping updates","relying on memory","ignoring the batch"],"Bulletins carry updates.")
H("881.d.1.D",4,"Service bulletins matter to refinish technicians because they:","announce corrections or changes to products and procedures",["list paint prices only","replace the training manual","are advertising"],"Stay current.")
H("881.d.2.A",3,"A shop plans a spot repair for one scratch and a full repaint for a faded roof. The painter is choosing:","the basic types of refinishing procedures for the damage",["a tire size","an oil grade","a wheel alignment"],"Match procedure to damage.")
H("881.d.2.A",4,"Blending into an adjacent panel is mainly done to:","hide the color transition so the repair is invisible",["add thickness","dry the paint","remove rust"],"Blends hide edges.")
H("881.d.2.B",3,"A student preps a fender, primes it, applies base and clear, then lets it cure per the data sheet. She is demonstrating:","proper preparation, application and refinishing with various paint systems",["engine tuning","brake service","tire mounting"],"Prep, apply, cure.")
H("881.d.2.B",4,"Switching from a solvent system to a waterborne system changes the need for:","different flash-off, equipment and air movement",["no changes at all","a new car","a different customer"],"Systems differ.")
H("881.d.2.C",3,"A painter adds 3.5 refinish hours at $48 per hour and $120 in materials to a paint order. The total is:","$288",["$168","$120","$403.50"],"3.5 × 48 = 168; plus 120 = 288.")
H("881.d.2.C",4,"Estimating paint cost requires counting labor hours and:","material charges for primer, base and clear",["the customer's age","the radio","tire wear"],"Labor plus materials.")
H("881.d.2.D",3,"A painter measures 4 parts paint, 1 part activator and 1 part reducer with a ratio stick. She is performing:","precision measurements of paint and materials",["guesswork","a visual guess","a free pour"],"Measure exactly.")
H("881.d.2.D",4,"A 6-ounce batch mixed at 2:1:1 uses how much of the paint component?","3 ounces",["1 ounce","6 ounces","2 ounces"],"Paint is 2 of 4 parts, so half.")
H("881.d.3.A",3,"Before spraying, a painter reads the safety data sheet and notes isocyanate exposure risks. She is:","identifying safety and personal health hazards according to OSHA regulations",["ignoring labels","skipping the sheet","guessing"],"Know the hazards.")
H("881.d.3.A",4,"Isocyanates in activators are a health concern mainly because they can:","cause asthma-like lung reactions and skin sensitization",["improve breathing","clean the lungs","cool the skin"],"Isocyanate hazard.")
H("881.d.3.B",3,"Before a shift, a painter checks that the booth's filters are clean and the airflow is within specification. She is:","inspecting the spray environment for compliance with federal, state and local regulations",["painting the booth","ignoring filters","cleaning the lobby"],"Booth compliance.")
H("881.d.3.B",4,"A spray booth with clogged filters can cause:","poor airflow, dirt in the finish and unsafe fumes",["cleaner air","faster curing only","less overspray"],"Filters matter.")
H("881.d.3.C",3,"Sandra puts on a fitted respirator, checks the seal and checks cartridge dates before mixing. She is:","selecting, using, inspecting and maintaining respiratory equipment per OSHA standards",["using a paper dust mask","skipping a fit check","sharing masks"],"Respirator fit and care.")
H("881.d.3.C",4,"A fit check on a respirator is done to make sure:","no air leaks around the seal",["the mask looks new","the mask is colorful","the mask is loud"],"Seal check.")
H("881.d.3.D",3,"A shop uses an air-supplied hood for waterborne and solvent spraying, tests the air quality and logs maintenance. This follows:","OSHA Regulation 1910.134 on respiratory protection",["a paint brand's ad","a customer's request","a school dress code"],"Respiratory standard.")
H("881.d.3.D",4,"Records of respirator fit testing and maintenance are kept to:","show compliance and protect worker health",["hide mistakes","save paper","reduce training"],"Documentation.")
H("881.d.3.E",3,"A painter chooses nitrile gloves, a paint suit and a hood with the respirator. She is:","selecting and using proper personal safety equipment",["wearing cotton gloves","skipping a suit","wearing sandals"],"PPE selection.")
H("881.d.3.E",4,"Nitrile gloves are preferred over latex for paints because they:","resist solvents and avoid latex allergies",["dissolve instantly","absorb paint","are free"],"Solvent resistance.")
H("881.d.3.F",3,"Luis checks the cord of a random orbital sander and uses the dust extraction hose. He is using:","hand and power tools and equipment commonly used in paint and refinishing",["only a brush","no tools","only a spray gun"],"Tool safety.")
H("881.d.3.F",4,"Before using a power sander, a technician should:","inspect it for damage and keep guards in place",["remove the guard","hold it by the cord","use it wet"],"Inspect first.")
H("881.d.3.G",3,"A shop collects used thinner and sets rags in a closed metal can instead of the trash. This is:","proper handling and disposal of environmentally hazardous materials",["ignoring regulations","dumping in the drain","burning rags"],"Hazmat disposal.")
H("881.d.3.G",4,"Solvent-soaked rags are stored in a closed approved container to prevent:","fire from spontaneous combustion and vapor release",["faster drying","cleaner floors","rag shortages"],"Fire prevention.")
H("881.d.3.H",3,"A shop evaluates a new low-VOC waterborne system and an infrared curing lamp. This shows:","knowledge of new and emerging paint and refinishing technologies",["resistance to change","outdated methods only","avoiding training"],"Emerging tech.")
H("881.d.3.H",4,"Waterborne basecoat is chosen in many shops because it:","lowers volatile organic compound emissions",["raises VOCs","is the cheapest option always","needs no training"],"Environmental benefit.")
H("881.d.4.A",3,"The shop manager walks the booth monthly with a checklist covering ventilation, storage and eyewash stations. She is:","performing regular audits and inspections to maintain compliance with safety, health and environmental regulations",["guessing","skipping inspections","painting"],"Audits catch problems.")
H("881.d.4.A",4,"Regular audits help a shop avoid:","fines, injuries and shutdowns",["compliance","productivity","safe work"],"Prevent violations.")
H("881.d.4.B",3,"A painter finds a hood is aluminum and a bumper is plastic and adjusts the prep for each. She is:","inspecting vehicle construction materials and the associated refinishing methods",["using one method for all","ignoring materials","guessing"],"Materials differ.")
H("881.d.4.B",4,"Aluminum panels need different preparation than steel because aluminum:","forms an oxide layer and needs specific cleaners and primers",["is a plastic","needs no prep","never corrodes"],"Aluminum prep.")
H("881.d.4.C",3,"A technician sees the paint is a factory single-stage finish on an older truck and chooses a compatible refinish plan. She is:","identifying different types of vehicle finishes and associated refinish techniques",["ignoring the finish","guessing","skipping prep"],"Know the finish.")
H("881.d.4.C",4,"A solvent-wipe test on an old paint finish helps determine if it is:","lacquer or enamel",["steel or aluminum","new or old oil","wet or dry"],"Finish ID.")
H("881.d.4.D",3,"A painter spots tiny circles around a sanding scratch and traces them back to feather-edging with coarse paper. She is:","inspecting, identifying and determining the cause of a paint defect",["ignoring it","hiding it","painting over it"],"Find the cause.")
H("881.d.4.D",4,"Fisheyes in a fresh finish are usually caused by:","surface contamination such as silicone or wax",["too much hardener","clean metal","cold booth only"],"Contamination.")
H("881.d.4.E",3,"A shop applies seam sealer and cavity wax after a panel replacement so moisture can't reach bare metal. They are discussing:","corrosion protection",["wheel balance","engine tuning","glass care"],"Rust protection.")
H("881.d.4.E",4,"Corrosion protection is restored after repairs because it:","prevents rust from starting at the repaired area",["adds weight","removes paint","speeds the job"],"Protect repaired metal.")
H("881.d.4.F",3,"After refinishing, a detailer washes the car, cleans the glass and wipes door jambs. She is:","demonstrating vehicle detailing",["spraying primer","sanding filler","mixing paint"],"Detail finish.")
H("881.d.4.F",4,"A final detailing step is done before delivery so the vehicle:","is clean and ready to hand over to the customer",["is dirty","is unfinished","has overspray"],"Customer-ready.")
H("881.d.5.A",3,"A painter uses a gauge to measure film thickness on an old finish before sanding. She is:","inspecting and identifying the type of finish, surface condition and film thickness",["guessing thickness","ignoring paint","skipping tests"],"Measure the film.")
H("881.d.5.A",4,"High film thickness readings warn a painter that:","too many layers may require stripping instead of another coat",["more paint is better","the panel is thin","no sanding is needed"],"Too much film.")
H("881.d.5.B",3,"Using 320-grit on a block, a painter smooths the edge of a chip so the old paint tapers into bare metal. She is:","featheredging areas to be refinished",["masking","buffing","detailing"],"Taper the edge.")
H("881.d.5.B",4,"Featheredging is done so that the repair edge:","won't show through the new finish",["shows clearly","creates a ridge","adds a color"],"No visible edge.")
H("881.d.5.C",3,"After sanding to bare metal, a painter applies an etching primer to the steel. She is:","applying a suitable metal treatment or primer",["buffing","masking","detailing"],"Treat bare metal.")
H("881.d.5.C",4,"Metal treatment primer on bare steel is used to:","help adhesion and resist corrosion",["speed rust","remove paint","thin the coat"],"Adhesion and protection.")
H("881.d.5.D",3,"Before spraying, Rae masks the windows, trim and adjacent panels with paper and tape. She is:","masking and protecting areas that will not be refinished",["spraying","buffing","sanding"],"Protect nearby surfaces.")
H("881.d.5.D",4,"Tape lines that aren't pressed down can allow:","overspray and fuzzy edges",["perfect lines","faster work","no mess"],"Seal the edge.")
H("881.d.5.E",3,"A painter mixes primer-surfacer with its reducer and activator, following the data sheet ratio. She is:","mixing primer, primer-surfacer or primer-sealer",["painting clearcoat","polishing","sanding"],"Mix primer.")
H("881.d.5.E",4,"A primer-surfacer is built to:","fill minor sanding scratches so the surface is smooth",["remove rust","dry instantly","add color"],"Fill and level.")
H("881.d.5.F",3,"A painter picks a gray undercoat shade that best helps a weak red topcoat cover in fewer coats. She is:","identifying a complementary color or shade of undercoat to improve coverage",["picking a random shade","ignoring color","using clear"],"Undercoat shade.")
H("881.d.5.F",4,"A shade of undercoat that matches the topcoat can improve:","hiding and reduce the number of topcoat layers",["rust","film cracks","thin metal"],"Better hiding.")
H("881.d.5.G",3,"A painter sprays two even coats of primer over the repaired spot, allowing flash time between coats. She is:","applying primer onto the surface of the repaired area",["buffing","detailing","removing decals"],"Prime the repair.")
H("881.d.5.G",4,"Applying primer too heavily in one pass can cause:","runs and long cure times",["perfect leveling","dry spray","faster drying"],"Light even coats.")
H("881.d.5.H",3,"A painter blows out cracks and moldings with an air gun before wiping the surface. She is:","removing dust from the area to be refinished, including cracks and moldings",["adding dust","painting","sanding"],"Clear hidden dust.")
H("881.d.5.H",4,"Dust left in a crack can later:","blow out onto the wet paint and cause dirt defects",["improve the finish","stay locked in","cure the paint"],"Blowout risk.")
H("881.d.5.I",3,"Using a lint-free cloth, a painter wipes the panel with a wax and grease remover then dries it with a second clean cloth. She is:","cleaning the area with a final cleaning solution",["sanding","masking","buffing"],"Final clean.")
H("881.d.5.I",4,"A two-rag wipe method is used so that:","dissolved contaminants are removed, not smeared back",["contaminants spread","paint dries","cloth wears faster"],"Wet then dry.")
H("881.d.5.J",3,"Right before spraying, a painter gently drags a tack cloth over the panel. She is:","removing dust or lint particles with a tack cloth",["sanding","buffing","masking"],"Last dust pass.")
H("881.d.5.J",4,"Pressing hard with a tack cloth is avoided because it can:","leave a sticky residue that hurts adhesion",["improve the finish","dry the panel","remove all dust"],"Light touch.")
H("881.d.5.K",3,"A painter rolls a sealer over primer to keep the topcoat from soaking in and to get an even color. She is:","applying a suitable sealer to the area being refinished",["buffing","masking","detailing"],"Sealer step.")
H("881.d.5.K",4,"A primer-sealer is used to:","create a uniform barrier between old finish and new paint",["add shine","remove color","thin paint"],"Barrier layer.")
H("881.d.5.L",3,"A painter sprays a chip-resistant coating on the lower rocker panels before color to resist road debris. She is:","applying a stone chip resistant coating",["buffing","detailing","masking"],"Chip protection.")
H("881.d.5.L",4,"Stone chip coating is most useful on:","lower panels and rocker areas hit by road debris",["the roof center","the interior","the windshield glass"],"Common chip zones.")
H("881.d.5.M",3,"A technician checks the part's stamped code to learn whether a bumper is rigid or flexible and picks the right flex additive. She is:","identifying types of plastic parts to be refinished",["painting","masking","buffing"],"Know the plastic.")
H("881.d.5.M",4,"Paint on a flexible bumper often needs a flex additive to:","prevent cracking when the part bends",["make it harder","increase rust","speed drying"],"Add flexibility.")
H("881.d.5.N",3,"A painter identifies a galvanized steel panel and a bare aluminum panel and picks the correct primer for each. She is:","identifying metal parts to be refinished and determining materials and preparation needed",["using one primer for all","guessing","ignoring metal types"],"Metal-specific prep.")
H("881.d.5.N",4,"Etching primer on aluminum is chosen because it:","bites into the oxide layer for good adhesion",["dissolves the metal","adds weight","removes paint"],"Adhesion on aluminum.")
H("881.d.6.A",3,"At the start of a shift, Amir takes apart his spray gun, cleans the cap and checks the booth and the air line for water. He is:","inspecting, cleaning and determining the condition of spray guns, the spray environment and related equipment",["spraying first","skipping cleaning","ignoring equipment"],"Check equipment.")
H("881.d.6.A",4,"A dirty gun cap or clogged air passage can cause:","spitting and a distorted spray pattern",["a perfect pattern","a cleaner finish","less paint use"],"Dirty gun, bad pattern.")
H("881.d.6.B",3,"Reading the data sheet, a painter picks a 1.3 mm fluid tip for basecoat and a 1.4 mm for clear. She is:","selecting spray gun setup, including fluid needle, nozzle and cap, for the product being applied",["guessing tip sizes","using one tip for all","ignoring directions"],"Match tip to material.")
H("881.d.6.B",4,"A thicker primer-surfacer generally needs:","a larger fluid tip than thin basecoat",["a smaller tip","no tip","a dry tip"],"Heavier material, larger tip.")
H("881.d.6.C",3,"Before spraying a test card, Kim adjusts the fluid knob, the air inlet pressure and the fan pattern knob. She is:","testing and adjusting a spray gun with fluid, air and pattern control valves",["painting a car","cleaning rags","sanding"],"Dial in the gun.")
H("881.d.6.C",4,"A spray pattern that is heavy in the middle and thin at the ends usually means:","the fan is too narrow or the air pressure is too low",["a perfect pattern","a clean gun","too much sanding"],"Pattern fault.")
H("881.d.6.D",3,"A painter explains that a pressure pot pushes paint to the gun with air pressure instead of relying on gravity. She is describing:","the operation of pressure spray equipment",["a wash bay","a tire changer","a sander"],"Pressure feed.")
H("881.d.6.D",4,"A pressure spray system is chosen for large jobs because it:","delivers a steady supply of heavy material to the gun",["stops spraying","uses no air","dries paint"],"Steady supply.")
H("881.d.7.A",3,"A painter finds the paint code on the vehicle information label in the door jamb. She is:","identifying the color code from the manufacturer's vehicle information label",["guessing the color","using the VIN only","ignoring the label"],"Find the code.")
H("881.d.7.A",4,"The paint code is used by the shop to:","look up the formula for the right color",["pick tire size","set tire pressure","find the owner"],"Code leads to formula.")
H("881.d.7.B",3,"Marco measures, stirs and strains the mixed paint through a filter before filling the cup. He is:","measuring, shaking, stirring, reducing, activating and straining refinish materials",["spraying dry","adding water randomly","skipping mixing"],"Proper mixing.")
H("881.d.7.B",4,"Straining paint before spraying helps by:","catching lumps and debris that cause defects",["adding dirt","thinning color","drying paint"],"Strain debris.")
H("881.d.7.C",3,"A painter holds the gun 6 to 8 inches from the panel, keeps it square and overlaps each pass by half. She is applying:","appropriate spray techniques, including arc, angle, distance and overlap",["random sweeps","a brush stroke","a dip method"],"Technique basics.")
H("881.d.7.C",4,"Tilting the gun at an angle at the end of a pass causes:","uneven film thickness and color shift",["even paint","perfect blends","faster drying"],"Keep it square.")
H("881.d.7.D",3,"Before painting the car, Jo sprays a test panel and holds it next to the fender to compare color. She is:","applying product on a test panel and checking for color match",["skipping a test","guessing","polishing"],"Test the match.")
H("881.d.7.D",4,"Color should be checked under:","more than one light source",["a dark room","no light","the booth floor"],"Metamerism.")
H("881.d.7.E",3,"On a work truck, a painter sprays one color with the gloss built in, without a separate clear. She is applying:","a single-stage topcoat",["a basecoat/clearcoat","a primer","a sealer"],"One-step color and gloss.")
H("881.d.7.E",4,"A single-stage finish differs from basecoat/clearcoat because it:","has color and gloss in one product",["needs two products","has no gloss","has no color"],"One product.")
H("881.d.7.F",3,"A painter blends basecoat into a door and then sprays clear over the repair panel. She is:","applying basecoat and clearcoat for panel blending and panel refinishing",["priming only","sanding only","detailing"],"Blend and clear.")
H("881.d.7.F",4,"The clearcoat is applied over basecoat to:","protect the color and add gloss",["remove color","thin the paint","soften the metal"],"Clear protects.")
H("881.d.7.G",3,"For a full repaint, a painter sprays color on every panel and then clear on the whole car. She is applying:","basecoat and clearcoat for overall refinishing",["a spot repair","a decal","a wash"],"Overall refinish.")
H("881.d.7.G",4,"Overall refinishing differs from a spot repair because:","every panel is painted instead of one area",["no clear is needed","no color is used","it skips prep"],"Whole vehicle.")
H("881.d.7.H",3,"After the basecoat dries, Ben removes a few dust nibs with fine paper before clear. He is:","removing nibs or imperfections from the basecoat",["adding nibs","buffing clear","masking"],"Clean the base.")
H("881.d.7.H",4,"Heavy sanding of metallic basecoat can cause:","cloudy or mottled color",["perfect color","a stronger finish","faster dry"],"Light touch.")
H("881.d.7.I",3,"A painter adds an adhesion promoter to a rigid plastic mirror housing before color. She is:","refinishing rigid or semi-rigid plastic parts",["refinishing steel","detailing glass","painting wheels"],"Plastic prep.")
H("881.d.7.I",4,"Rigid plastic can be painted without flex additive because it:","does not bend during normal use",["is soft","bends easily","cracks constantly"],"No flex needed.")
H("881.d.7.J",3,"A painter adds flex agent to the clearcoat for a bumper cover that bends in a light impact. She is:","refinishing flexible plastic parts",["refinishing metal","detailing glass","masking"],"Flexible plastic.")
H("881.d.7.J",4,"Without a flex agent, a hardened coating on a bumper may:","crack or flake when the part flexes",["stay perfect","get stronger","bounce back"],"Cracking.")
H("881.d.7.K",3,"A tri-coat pearl white requires a basecoat, a mid-coat and a clear. The painter is applying:","multi-stage coats for panel blending and overall refinishing",["a single coat","only primer","only clear"],"Tri-coat.")
H("881.d.7.K",4,"On a tri-coat finish, the number of mid-coat passes affects:","the final color appearance",["tire pressure","the owner's name","the fuel type"],"Mid-coat controls color.")
H("881.d.7.L",3,"A painter looks up a formula and weighs each toner on a scale to match the code. She is:","identifying and mixing paint using a formula",["guessing","using random toners","using a brush"],"Formula mixing.")
H("881.d.7.L",4,"Weighing toners in grams instead of eyeballing helps ensure:","the color matches the formula repeatably",["a random color","wasted paint","a faded color"],"Weigh for accuracy.")
H("881.d.7.M",3,"On a bright red job, a painter notices the base doesn't cover after three coats and picks a different undercoat. She is:","identifying poor hiding colors and determining necessary action",["ignoring it","adding more clear","skipping prep"],"Poor hiding.")
H("881.d.7.M",4,"Reds and yellows often have poor hiding because they:","use transparent pigments",["are thick","contain metal","are too dark"],"Transparent pigments.")
H("881.d.7.N",3,"A painter adds a tiny amount of black toner to darken a close but slightly light mix before spraying. She is:","tinting color using a formula to achieve a blendable match",["ignoring the match","starting over","adding clear"],"Tint the color.")
H("881.d.7.N",4,"When tinting, a painter should add toner:","in very small amounts and recheck the match",["by the cupful","without checking","all at once"],"Small steps.")
H("881.d.7.O",3,"The first formula looks off, so Dee checks a variant formula in the database for the same color code. She is:","identifying an alternative color formula to achieve a blendable match",["quitting","ignoring variants","guessing"],"Variants.")
H("881.d.7.O",4,"A paint code can have several variants because:","factory color varies between plants and batches",["every car is identical","paint never changes","only one plant exists"],"Variants exist.")
H("881.d.7.P",3,"A painter compares the equipment and prep for a petroleum-based system and a waterborne system. She is identifying:","the material, equipment and preparation differences between petroleum-based and waterborne systems",["the same needs for both","no differences","only price"],"System differences.")
H("881.d.7.P",4,"Waterborne basecoats generally need:","stronger air movement to flash off and stainless steel equipment",["no air flow","iron tools","solvent washes only"],"Waterborne needs.")
H("881.d.8.A",3,"A detailer applies a vinyl pinstripe and a decal after the clearcoat has cured. She is:","applying decals, transfers, tapes, woodgrains and pinstripes",["sanding","priming","masking"],"Graphics step.")
H("881.d.8.A",4,"Decals are applied after cure so that:","the finish won't trap solvents or wrinkle",["they stick worse","they stay wet","they peel off"],"Cure first.")
H("881.d.8.B",3,"A painter wet-sands a few dust nibs with 1500-grit and then compounds and polishes the clear. She is:","sanding, buffing and polishing a finish to remove defects",["priming","masking","spraying"],"Finish work.")
H("881.d.8.B",4,"Buffing too long on one spot can:","burn through the clearcoat",["improve gloss","add paint","cool the panel"],"Don't burn through.")
H("881.d.8.C",3,"At delivery prep, Rosa vacuums the interior, washes the exterior and cleans the windows. She is:","cleaning the vehicle interior, exterior and glass",["priming","sanding","masking"],"Clean the car.")
H("881.d.8.C",4,"Cleaning the vehicle before delivery helps the customer see:","the quality of the work without dirt hiding it",["a dirty job","unfinished work","paint defects"],"Presentation.")
H("881.d.8.D",3,"A detailer wipes tape residue from the door jambs and cleans the edges of the hood. She is:","cleaning body openings such as door jambs and edges",["spraying","sanding","masking"],"Jambs.")
H("881.d.8.D",4,"Overlooked jambs can leave:","dirt and overspray the customer will notice",["a spotless job","no evidence","fresh paint"],"Jambs show.")
H("881.d.8.E",3,"A detailer uses a clay bar on the glass and trim to lift fine paint mist. She is:","removing overspray",["adding overspray","painting","sanding"],"Overspray removal.")
H("881.d.8.E",4,"Clay bar lubricant is used so that the bar:","glides without scratching the finish",["dries out","scratches more","stops working"],"Lube the clay.")
H("881.d.8.F",3,"Before releasing a car, the lead painter walks through a checklist: color match, gloss, texture, edges and cleanliness. He is:","completing quality control using a checklist",["skipping checks","guessing","ignoring defects"],"QC checklist.")
H("881.d.8.F",4,"A checklist is used at the end of a job to:","catch problems before the customer sees them",["add problems","skip steps","save paper"],"Catch errors.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_132.jsonl"))
